        // FAQ
        "faq.q1": "How do I choose the right coach?",
        "faq.a1": "Start by watching coach introduction videos to get a sense of their style and approach. Review their credentials, specialties, and client recommendations. Many coaches offer a free initial consultation to ensure a good fit.",
        "faq.q2": "What's the difference between online and in-person coaching?",
        "faq.a2": "Both formats are equally effective. Online coaching offers flexibility and convenience, while in-person sessions may feel more personal. Many clients start online and occasionally meet in person, or vice versa.",
        "faq.q3": "How much does coaching typically cost?",
        "faq.a3": "Coaching rates vary based on the coach's experience, specialization, and location. Most coaches on our platform offer sessions ranging from €50 to €250 per hour. Many offer package deals for multiple sessions.",
