        "about.heroTitle": "Connecting You With the Perfect Coach",
        "about.heroSubtitle": "CoachSearching is the trusted platform for finding verified professional coaches who can help you achieve your personal and professional goals.",
        "about.mission.text1": "We believe that everyone deserves access to quality coaching. Our mission is to democratize professional development by connecting individuals with verified, experienced coaches who can guide them toward their goals.",
