        // Pricing FAQ
        "pricing.faq.commissionQ": "Do you take a commission on my coaching sessions?",
        "pricing.faq.commissionA": "No, never. You arrange payments directly with your clients however you prefer – bank transfer, PayPal, your own invoicing system. We only facilitate the initial connection through discovery call bookings.",
        "pricing.faq.discoverySlotQ": "What counts as a \"discovery call slot\"?",
        "pricing.faq.discoverySlotA": "A discovery call slot is one available time window when potential clients can book a free introductory call with you. On the Free plan, you can offer 1 slot per week. Premium coaches can offer unlimited slots.",
        "pricing.faq.coachNotesQ": "What is Coach Notes?",
        "pricing.faq.coachNotesA": "Coach Notes is a simple client management tool. When someone books a discovery call with you, they're added to your client list. You can then keep private notes about each client – what you discussed, their goals, progress, and anything else you want to remember. Only you can see these notes.",
        "pricing.faq.prioritySearchQ": "What does \"Priority search placement\" mean?",
        "pricing.faq.prioritySearchA": "Premium coaches appear higher in search results when potential clients are looking for a coach. You'll also get a \"Featured Coach\" badge that makes your profile stand out.",
        "pricing.faq.cancelNotesQ": "What happens to my Coach Notes if I cancel Premium?",
        "pricing.faq.cancelNotesA": "Your profile stays active on the Free plan. You keep read-only access to your existing Coach Notes, but cannot add or edit notes. Your discovery call slots reduce to 1 per week, and your profile reverts to Free tier limits.",
        "pricing.faq.upgradeDowngradeQ": "Can I upgrade or downgrade anytime?",
        "pricing.faq.upgradeDowngradeA": "Yes. Upgrades take effect immediately. Downgrades take effect at the end of your current billing period.",
        "pricing.faq.launchOfferQ": "What's the Launch Offer?",
        "pricing.faq.launchOfferA": "Early supporters get Premium for €19/month (instead of €29/month) for their entire first year. This offer is limited to the first 100 coaches.",

