        "hiw.faq.a1": "Nein, das Durchsuchen von Coaches und die Kontoerstellung sind völlig kostenlos. Sie zahlen nur, wenn Sie eine Sitzung buchen.",
        "hiw.faq.q2": "Wie lange dauert es, mit einem Coach gematcht zu werden?",
        "hiw.faq.a2": "Unser KI-Quiz dauert etwa 5 Minuten und liefert sofortige Empfehlungen. Sie können danach sofort eine Sitzung buchen.",
        "hiw.faq.q3": "Was ist, wenn ich mit meinem Coach nicht zufrieden bin?",
        "hiw.faq.a3": "Wir möchten, dass Sie das perfekte Match finden. Wenn Sie nicht zufrieden sind, kontaktieren Sie den Support und wir helfen Ihnen, einen besseren Coach zu finden.",
        "hiw.faq.q4": "Kann ich den Coach wechseln?",
        "hiw.faq.a4": "Absolut! Sie können verschiedene Coaches ausprobieren, bis Sie den richtigen für sich gefunden haben.",

        // About Page - Extended (German)
        "about.pageTitle": "Über CoachSearching",
        "about.pageDescription": "Erfahren Sie mehr über CoachSearching, die professionelle Coaching-Plattform, die Kunden weltweit mit verifizierten Coaches verbindet.",
        "about.heroTitle": "Wir verbinden Sie mit dem perfekten Coach",
        "about.heroSubtitle": "CoachSearching ist die vertrauenswürdige Plattform, um verifizierte professionelle Coaches zu finden, die Ihnen helfen können, Ihre persönlichen und beruflichen Ziele zu erreichen.",
        "about.mission.text1": "Wir glauben, dass jeder Zugang zu qualitativ hochwertigem Coaching verdient. Unsere Mission ist es, berufliche Entwicklung zu demokratisieren, indem wir Menschen mit verifizierten, erfahrenen Coaches verbinden, die sie zu ihren Zielen führen können.",
        "about.mission.text2": "Ob Sie eine Führungskraft sind, die Führungsberatung sucht, ein Berufstätiger, der einen Karrierewechsel navigiert, oder jemand, der sein persönliches Leben verbessern möchte - wir helfen Ihnen, den richtigen Coach für Ihre Reise zu finden.",
        "about.mission.imageAlt": "Coaching-Sitzung",
