        "about.values.transparentDesc": "Keine versteckten Gebühren. Sehen Sie genau, was Sie zahlen, bevor Sie eine Sitzung buchen.",
        "about.values.reviews": "Verifizierte Empfehlungen",
        "about.values.reviewsDesc": "Echte Empfehlungen von echten Kunden helfen Ihnen, fundierte Entscheidungen über Ihren Coach zu treffen.",
