        // Pricing FAQ
        "pricing.faq.commissionQ": "Nehmen Sie eine Provision auf meine Coaching-Sitzungen?",
        "pricing.faq.commissionA": "Nein, niemals. Sie vereinbaren Zahlungen direkt mit Ihren Kunden, wie Sie möchten – Banküberweisung, PayPal, Ihr eigenes Rechnungssystem. Wir vermitteln nur den ersten Kontakt durch Kennenlern-Gespräche.",
        "pricing.faq.discoverySlotQ": "Was zählt als \"Kennenlern-Termin\"?",
        "pricing.faq.discoverySlotA": "Ein Kennenlern-Termin ist ein verfügbares Zeitfenster, in dem potenzielle Kunden ein kostenloses Einführungsgespräch mit Ihnen buchen können. Im kostenlosen Tarif können Sie 1 Termin pro Woche anbieten. Premium-Coaches können unbegrenzt Termine anbieten.",
        "pricing.faq.coachNotesQ": "Was ist Coach Notes?",
        "pricing.faq.coachNotesA": "Coach Notes ist ein einfaches Kundenmanagement-Tool. Wenn jemand ein Kennenlern-Gespräch bei Ihnen bucht, wird er zu Ihrer Kundenliste hinzugefügt. Sie können dann private Notizen zu jedem Kunden führen – was Sie besprochen haben, ihre Ziele, Fortschritte und alles andere, woran Sie sich erinnern möchten. Nur Sie können diese Notizen sehen.",
        "pricing.faq.prioritySearchQ": "Was bedeutet \"Bevorzugte Such-Platzierung\"?",
        "pricing.faq.prioritySearchA": "Premium-Coaches erscheinen höher in den Suchergebnissen, wenn potenzielle Kunden nach einem Coach suchen. Sie erhalten außerdem ein \"Empfohlener Coach\" Badge, das Ihr Profil hervorhebt.",
        "pricing.faq.cancelNotesQ": "Was passiert mit meinen Coach Notes, wenn ich Premium kündige?",
        "pricing.faq.cancelNotesA": "Ihr Profil bleibt im kostenlosen Tarif aktiv. Sie behalten Lesezugriff auf Ihre bestehenden Coach Notes, können aber keine Notizen hinzufügen oder bearbeiten. Ihre Kennenlern-Termine werden auf 1 pro Woche reduziert, und Ihr Profil kehrt zu den Limits des kostenlosen Tarifs zurück.",
        "pricing.faq.upgradeDowngradeQ": "Kann ich jederzeit upgraden oder downgraden?",
        "pricing.faq.upgradeDowngradeA": "Ja. Upgrades werden sofort wirksam. Downgrades werden am Ende Ihres aktuellen Abrechnungszeitraums wirksam.",
        "pricing.faq.launchOfferQ": "Was ist das Einführungsangebot?",
        "pricing.faq.launchOfferA": "Frühe Unterstützer erhalten Premium für €19/Monat (statt €29/Monat) für ihr gesamtes erstes Jahr. Dieses Angebot ist auf die ersten 100 Coaches begrenzt.",

