        "hiw.faq.a1": "No, ver coaches y crear una cuenta es completamente gratis. Solo pagas cuando reservas una sesión.",
        "hiw.faq.q2": "¿Cuánto tiempo toma ser emparejado con un coach?",
        "hiw.faq.a2": "Nuestro quiz de IA toma unos 5 minutos y proporciona recomendaciones instantáneas. Puedes reservar una sesión inmediatamente después.",
        "hiw.faq.q3": "¿Qué pasa si no estoy satisfecho con mi coach?",
        "hiw.faq.a3": "Queremos que encuentres el match perfecto. Si no estás satisfecho, contacta a soporte y te ayudaremos a encontrar uno mejor.",
        "hiw.faq.q4": "¿Puedo cambiar de coach?",
        "hiw.faq.a4": "¡Absolutamente! Eres libre de probar diferentes coaches hasta encontrar el adecuado para ti.",

