        "about.heroSubtitle": "CoachSearching es la plataforma confiable para encontrar coaches profesionales verificados que pueden ayudarte a alcanzar tus metas personales y profesionales.",
        "about.mission.text1": "Creemos que todos merecen acceso a coaching de calidad. Nuestra misión es democratizar el desarrollo profesional conectando individuos con coaches verificados y experimentados.",
        "about.mission.text2": "Ya seas un ejecutivo buscando orientación de liderazgo, un profesional navegando un cambio de carrera, o alguien buscando mejorar su vida personal, estamos aquí para ayudarte a encontrar el coach adecuado.",
