        "about.heroSubtitle": "CoachSearching est la plateforme de confiance pour trouver des coachs professionnels vérifiés qui peuvent vous aider à atteindre vos objectifs personnels et professionnels.",
        "about.mission.text1": "Nous croyons que tout le monde mérite l'accès à un coaching de qualité. Notre mission est de démocratiser le développement professionnel en connectant les individus avec des coachs vérifiés et expérimentés qui peuvent les guider vers leurs objectifs.",
