        // About Page - Extended
        "about.pageTitle": "Chi è CoachSearching",
        "about.pageDescription": "Scopri CoachSearching, la piattaforma di coaching professionale che connette i clienti con coach verificati in tutto il mondo.",
        "about.heroTitle": "Connetterti al Coach Perfetto",
        "about.heroSubtitle": "CoachSearching è la piattaforma di fiducia per trovare coach professionisti verificati che possono aiutarti a raggiungere i tuoi obiettivi personali e professionali.",
        "about.mission.text1": "Crediamo che tutti meritino accesso a un coaching di qualità. La nostra missione è democratizzare lo sviluppo professionale connettendo le persone con coach verificati ed esperti che possono guidarle verso i loro obiettivi.",
        "about.mission.text2": "Che tu sia un dirigente in cerca di guida sulla leadership, un professionista che sta navigando un cambio di carriera, o qualcuno che vuole migliorare la propria vita personale, siamo qui per aiutarti a trovare il coach giusto per il tuo percorso.",
