        "categoryPage.relationship-coaching.faq1A": "Il coaching relazionale è orientato al futuro e focalizzato sugli obiettivi, mentre la terapia spesso affronta problemi passati e salute mentale. Il coaching lavora con individui o coppie in cerca di miglioramento, non intervento di crisi.",
