        "categoryPage.relationship-coaching.faq3Q": "Come può il coaching relazionale aiutare il mio matrimonio?",
        "categoryPage.relationship-coaching.faq3A": "Il coaching relazionale aiuta le coppie a migliorare la comunicazione, riaccendere la connessione, navigare le transizioni, allineare gli obiettivi e sviluppare strumenti per il successo relazionale continuo.",

